ALLOWED = {
    "new":           {"triage"},
    "triage":        {"investigating", "closed"},
    "investigating": {"escalated", "closed"},
    "escalated":     {"closed"},
    "closed":        set(),
}
VERDICTS = {"true_positive", "benign_true_positive",
            "false_positive", "undetermined"}

def move(case, to, note="", verdict=None):
    if to not in ALLOWED[case["state"]]:
        raise ValueError(f"{case['state']} cannot go to {to}")
    if not note.strip():
        raise ValueError("every move needs a note: what you saw and did")
    if to == "closed" and verdict not in VERDICTS:
        raise ValueError("closing needs a verdict")
    case["history"].append((case["state"], to, note))
    case["state"], case["verdict"] = to, verdict
    return case

