import json

def build_tree(events):
    """Link Sysmon Event ID 1 records by GUID, not by PID:
    Windows reuses PIDs, GUIDs are unique per process."""
    procs = {e["ProcessGuid"]: e for e in events if e["EventID"] == 1}
    children = {}
    for e in procs.values():
        children.setdefault(e["ParentProcessGuid"], []).append(e)
    roots = [e for e in procs.values()
             if e["ParentProcessGuid"] not in procs]
    return roots, children

def show(node, children, depth=0):
    name = node["Image"].split("\\")[-1]
    print(f'{"   " * depth}{name} (pid {node["ProcessId"]}) '
          f'{node["UtcTime"][11:19]}  {node["CommandLine"][:48]}')
    kids = sorted(children.get(node["ProcessGuid"], []),
                  key=lambda e: e["UtcTime"])
    for kid in kids:
        show(kid, children, depth + 1)

with open("sysmon_events.json") as f:
    roots, children = build_tree(json.load(f))
for r in roots:
    show(r, children)

from statistics import median

def egress_outliers(daily_mb, today_mb, factor=10, floor_mb=500):
    """daily_mb: {host: [MB sent on each of the last N days]}
    today_mb: {host: MB sent today}. Compare each host with
    ITS OWN history, not with the fleet average."""
    out = []
    for host, today in today_mb.items():
        base = median(daily_mb.get(host, [0])) or 1
        ratio = today / base
        if today >= floor_mb and ratio >= factor:
            out.append((host, today, base, round(ratio, 1)))
    return sorted(out, key=lambda r: -r[3])

