import ipaddress

KNOWN_NETS = [ipaddress.ip_network(n) for n in
              ("192.0.2.0/24",)]          # SYNTHETIC office egress range
RECON = {"ListBuckets", "GetCallerIdentity", "ListUsers",
         "ListAccessKeys"}

def key_kind(key_id):
    if key_id.startswith("AKIA"):
        return "long-term (IAM user)"
    if key_id.startswith("ASIA"):
        return "temporary (STS)"
    return "unknown"

def review(events):
    """events: simplified CloudTrail records for ONE access key."""
    notes = []
    new_ips = {e["sourceIPAddress"] for e in events
               if not any(ipaddress.ip_address(e["sourceIPAddress"]) in n
                          for n in KNOWN_NETS)}
    if new_ips:
        notes.append(f"calls from unfamiliar IPs: {sorted(new_ips)}")
    names = [e["eventName"] for e in events]
    if RECON & set(names):
        notes.append(f"discovery calls: {sorted(RECON & set(names))}")
    reads = names.count("GetObject")
    if reads > 100:
        notes.append(f"{reads} object reads: possible bulk collection")
    return key_kind(events[0]["accessKeyId"]), notes

