from collections import Counter

RECOVERY_KILLERS = ("delete shadows", "shadowcopy delete",
                    "delete catalog", "recoveryenabled no")

def precursors(file_events, proc_events, per_min_limit=200):
    """file_events: (minute, host, action) tuples from EDR or Sysmon.
    proc_events: (minute, host, command_line) tuples."""
    alerts = []
    writes = Counter((m, h) for m, h, a in file_events
                     if a in ("rename", "modify"))
    for (minute, host), n in sorted(writes.items()):
        if n > per_min_limit:
            alerts.append((minute, host, f"{n} file changes/min"))
    for minute, host, cmd in proc_events:
        low = cmd.lower()
        if any(k in low for k in RECOVERY_KILLERS):
            alerts.append((minute, host, f"recovery tampering: {cmd}"))
    return sorted(alerts)

